  1→<script setup lang="ts">
  2→import { ref, computed, watch, onMounted } from 'vue';
  3→import { useRoute, useRouter } from 'vue-router';
  4→import prettyMs from 'pretty-ms';
  5→import { motion, AnimatePresence, stagger } from 'motion-v';
  6→import { useDateRange, type ViewMode } from '@/composables/useDateRange';
  7→import { getHistoryLogs } from '@/db/service';
  8→import type { IHistoryLog } from '@/db/types';
  9→import DateNavigator from '@/components/DateNavigator.vue';
 10→import { formatDate, parseDate } from '@/utils/dateUtils';
 11→
 12→const contentVariants = {
 13→  hidden: { opacity: 0 },
 14→  show: {
 15→    opacity: 1,
 16→    transition: { delayChildren: stagger(0.08) },
 17→  },
 18→};
 19→
 20→const cardVariant = {
 21→  hidden: { opacity: 0, y: 12 },
 22→  show: { opacity: 1, y: 0, transition: { duration: 0.25 } },
 23→};
 24→
 25→const listContainerVariants = {
 26→  hidden: { opacity: 0 },
 27→  show: {
 28→    opacity: 1,
 29→    transition: { delayChildren: stagger(0.04) },
 30→  },
 31→};
 32→
 33→const listItemVariants = {
 34→  hidden: { opacity: 0, x: -12 },
 35→  show: { opacity: 1, x: 0, transition: { duration: 0.25 } },
 36→  exit: { opacity: 0, x: 12, transition: { duration: 0.15 } },
 37→};
 38→
 39→const route = useRoute();
 40→const router = useRouter();
 41→const { view, date, startDate, endDate, label, next, prev, goToday, isToday, canNext } = useDateRange();
 42→
 43→const hostname = computed(() => route.query.hostname as string | undefined);
 44→const path = computed(() => route.query.path as string | undefined);
 45→
 46→const logs = ref<IHistoryLog[]>([]);
 47→
 48→const fetchData = async () => {
 49→  try {
 50→    logs.value = await getHistoryLogs(startDate.value, endDate.value, hostname.value, path.value);
 51→  } catch (e) {
 52→    console.error('Failed to fetch history', e);
 53→  }
 54→};
 55→
 56→watch([startDate, endDate, hostname, path], fetchData);
 57→onMounted(fetchData);
 58→
 59→const title = computed(() => {
 60→  if (path.value) return 'Page History';
 61→  if (hostname.value) return 'Site History';
 62→  return 'History';
 63→});
 64→
 65→const subtitle = computed(() => {
 66→  if (path.value) return path.value;
 67→  if (hostname.value) return hostname.value;
 68→  return 'All Activity';
 69→});
 70→
 71→const goBack = () => {
 72→  router.back();
 73→};
 74→
 75→const updateView = (v: ViewMode) => {
 76→  view.value = v;
 77→};
 78→
 79→const formatTime = (ts: number) => {
 80→  return new Date(ts).toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' });
 81→};
 82→
 83→const groupedLogs = computed(() => {
 84→  const groups: Record<string, IHistoryLog[]> = {};
 85→  logs.value.forEach(log => {
 86→    const d = log.date;
 87→    if (!groups[d]) groups[d] = [];
 88→    groups[d].push(log);
 89→  });
 90→  // Sort keys desc
 91→  return Object.keys(groups).sort().reverse().map(date => ({
 92→    date,
 93→    logs: groups[date]
 94→  }));
 95→});
 96→
 97→const formatDateLabel = (d: string) => {
 98→    const dateObj = parseDate(d);
 99→    const today = new Date();
100→    const todayStr = formatDate(today);
101→    if (d === todayStr) return 'Today';
102→    return dateObj.toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' });
103→};
104→
105→const formatLogPath = (log: IHistoryLog) => {
106→  return hostname.value ? log.path : `${log.hostname}${log.path}`;
107→};
108→
109→const eventSourceConfig: Record<string, { icon: string; tip: string }> = {
110→  tab_activated: { icon: '⇥', tip: 'Tab Switch' },
111→  navigation: { icon: '↻', tip: 'Web Navigation' },
112→  window_focus: { icon: '◎', tip: 'Window Focus' },
113→  idle_resume: { icon: '▶', tip: 'Idle Resume' },
114→  alarm: { icon: '⏱', tip: 'Periodic Save' },
115→};
116→</script>
117→
118→<template>
119→  <div class="flex flex-col min-h-0 bg-base-100">
120→    <!-- Header -->
121→    <div class="navbar bg-base-100 sticky top-0 z-30 border-b border-base-200 min-h-12 px-2">
122→      <div class="navbar-start w-1/4">
123→        <div class="tooltip tooltip-right" data-tip="Back">
124→          <button class="btn btn-ghost btn-circle btn-sm" aria-label="Go back" @click="goBack">
125→            <svg class="size-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
126→              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 19l-7-7 7-7" />
127→            </svg>
128→          </button>
129→        </div>
130→      </div>
131→      <div class="navbar-center w-2/4 justify-center flex-col gap-0.5">
132→        <h1 class="text-sm font-bold truncate max-w-37.5">
133→          {{ title }}
134→        </h1>
135→        <div class="text-[10px] text-base-content/60 font-mono truncate max-w-50">
136→           {{ subtitle }}
137→        </div>
138→      </div>
139→      <div class="navbar-end w-1/4"></div>
140→    </div>
141→
142→    <!-- Date Navigator -->
143→    <DateNavigator
144→      :view="view"
145→      :label="label"
146→      :can-next="canNext"
147→      :is-today="isToday"
148→      @update:view="updateView"
149→      @prev="prev"
150→      @next="next"
151→      @today="goToday"
152→    />
153→
154→    <!-- List -->
155→    <motion.div class="flex-1 p-4" :variants="contentVariants" initial="hidden" animate="show">
156→      <AnimatePresence mode="wait">
157→        <motion.div
158→          v-if="logs.length === 0"
159→          key="empty"
160→          class="flex flex-col items-center justify-center py-10 gap-2 opacity-60"
161→          :initial="{ opacity: 0 }"
162→          :animate="{ opacity: 1 }"
163→          :exit="{ opacity: 0 }"
164→        >
165→          <svg class="size-12 text-base-content/30" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
166→          <div class="text-sm font-medium">No history recorded</div>
167→          <div class="text-xs">No activity found for this period.</div>
168→        </motion.div>
169→
170→        <motion.div v-else key="logs" class="flex flex-col gap-4" :variants="listContainerVariants" initial="hidden" animate="show">
171→          <motion.div v-for="group in groupedLogs" :key="group.date" class="flex flex-col gap-1" :variants="listItemVariants">
172→             <div class="sticky top-0 bg-base-100/95 backdrop-blur-sm z-10 px-2 py-1 text-xs font-bold text-base-content/50 uppercase border-b border-base-200">
173→               {{ formatDateLabel(group.date) }}
174→             </div>
175→
176→             <motion.div
177→               v-for="log in group.logs"
178→               :key="log.id || log.startTime"
179→               class="flex items-center gap-3 p-2 hover:bg-base-200/50 rounded-box transition-colors text-left border-b border-base-100 last:border-0"
180→               :variants="{ hidden: { opacity: 0 }, show: { opacity: 1 } }"
181→             >
182→                <div class="flex items-center gap-1.5 shrink-0 opacity-60">
183→                  <div
184→                    v-if="log.eventSource && eventSourceConfig[log.eventSource]"
185→                    class="tooltip tooltip-right"
186→                    :data-tip="eventSourceConfig[log.eventSource].tip"
187→                  >
188→                    <span class="text-[10px]">{{ eventSourceConfig[log.eventSource].icon }}</span>
189→                  </div>
190→                  <div class="font-mono text-xs font-bold w-10">{{ formatTime(log.startTime) }}</div>
191→                </div>
192→
193→                <div class="flex flex-col flex-1 min-w-0">
194→                  <div class="font-medium text-xs truncate" :title="log.title || 'Untitled'">
195→                    {{ log.title || 'Untitled' }}
196→                  </div>
197→                  <div class="text-[10px] text-base-content/50 truncate font-mono" :title="log.path">
198→                    {{ formatLogPath(log) }}
199→                  </div>
200→                </div>
201→
202→                <div class="font-mono text-xs font-bold opacity-80 shrink-0">
203→                   {{ prettyMs(log.duration, { compact: true }) }}
204→                </div>
205→             </motion.div>
206→          </motion.div>
207→
208→          <div v-if="logs.length >= 2000" class="text-center py-4 text-xs text-base-content/50">
209→             History limit reached (2000 items). Refine date range to see more.
210→          </div>
211→        </motion.div>
212→      </AnimatePresence>
213→    </motion.div>
214→  </div>
215→</template>
216→

